) AS (
  VALUES 
    (217::BIGINT, 'Un mae muy chill, califica suave, no se estresa mucho con las evaluaciones, quices y examen faciles. Dura bastante en revisar pero fuera de eso. Ayuda en las clases, no sabe mucho de fisica 2 pero lo intenta'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7f2abe0af9e461c4fb5cbb30e88787b79e5080679f27d79cb4d99db30d928bbc'::TEXT, ARRAY[631]::BIGINT[]),
    (217::BIGINT, 'no le va a entender absolutamente nada, literal espera que uno sepa todo y se enoja si uno le pregunta y llega a ser muy grosero. califica suavesisimo entonces sepa no se va a quedar, si es la unica opcion que queda no le irá mal tampoco, pero existen mejores la verdad.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e1b1efda6d93bdfd90da08ef75e86cba4a8c02fc205fa573f980bef78fdb3d3d'::TEXT, ARRAY[631]::BIGINT[]),
    (217::BIGINT, 'La materia se puede complicar muy fácilmente y la verdad no es muy bueno explicando, pero si uno le pide ayuda el man hace las cosas como puede la verdad, es de poner mucha atención y apoyarse en los compañeros la verdad'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, '2df70cff6d5de2215766d5fccc8c2242d5fdf62c6bacf82816ae7709eec7c595'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Explica enredado, pero si le pregunta fijo lo ayuda. Dejo los quizzes muy al final pero virtuales. Califica suave y tarda en dar resultados. El curso es mantequilla con que arme un buen grupo de 3 se pasa caminando.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5f41ddac3a15e1be12aa8bdcdd7b58ccc405b491b8c1e41f0a2494b2c051e098'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'el mae ayuda mucho con los reportes es calmado, tranquilo, a veces habla más paja de lo que toca. Me tocó hacer los quizes online, demasiado fáciles. El mae ayuda mucho con los informes. Recomendado para pasar el curso al suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-04T00:00:00+00:00'::TIMESTAMPTZ, '7fabbdc14f5cf8cb0e97b25fe310c361a6fac69d754a5ffb3f574a1324ceb97b'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Para lab es un profe ni fu ni fa, pero para este curso de mantequilla esta bien'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '99ba197b159a8f1e12a8e1159d94bf288cb37024e502f38387f7b1b84486eece'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Es un curso mantequilla entonces si quiere pasar facil se lo recomiendo eso si, no es muy bueno explicanco entonces si matricula con él es mejor que ya sepa usar excel. Califica justo y los quices los hace virtuales'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'c7a9438f85c32e09795611411abd7f188a070a4d33d1463ff7dd34f86a4dc231'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Aunque el profesor hace el curso sencillo y realmente facil de pasar, como profesor es realmente malo. No es bueno explicando, siempre se hace un enruedo, no califica bien y además tienen una actitud algo fea. Las horas de consulta no sirven, sale uno más confundido. Terrible profesor de física'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'fdf0864058241755e846783f43e7ca7bd5c1a6ac81fb9f2b97ce2864aa9f9548'::TEXT, ARRAY[3257]::BIGINT[]),
    (217::BIGINT, 'Buen profesor, siempre responde la dudas, ya sea en clase o por el teams. Ayuda bastante para el cálculo de incertidumbres y para el formato de los informes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '962545caa1c87472cddd63686b18d3f0d62417df8301e39c12282f02c9bb2121'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Para laboratorio de física sí es recomedanble, para teoría de física general I no se lo recomendaría. El profe da explicaciones bastante largas y aburridas, así que cuesta prestarle atención. Lo bueno de él es que sí está dispuesto a ayudarlo si necesita, y que no califica tan duro.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2024-11-13T00:00:00+00:00'::TIMESTAMPTZ, '7283a7024a15e43a22154a9cc7db60e31d2042f14207d533b356e3c953b444d2'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'El profe siempre está muy dispuesto a ayudar con consultas, es buena nota y ayuda con la parte práctica si uno ocupa. Es rudo calificando los 3 informes y la expo, a veces se tarda explicando teoría pero si uno le pone ganas pasa muy bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f4e13c8daca5fef6d9a430ac559c10ecdf6d12c6e97f35da6eb0a8a01a1c8a75'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Es fácil y demás pero aveces se duerme en clases, pero en consultas todo buena nota'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-18T00:00:00+00:00'::TIMESTAMPTZ, '721cf0a92cf81398ad7210453a0c42096cc0dcf636a61e5ddc1fc03b0d8ebe6e'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'El profe es buena nota, está dispuesto a aclarar dudas siempre. No califica tan duro'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '5247f8c81c66003253836a1836530f42fd5d2cd86ebc6abc8df3a380903a712c'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'No lo recomendaría para teoría, pero hace que lab sea fácil, habla un poco monótono y lento pero es muy amable, y hace las clases relativamente rápidas, para lab lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8e5d2c18f352ae58a37b48bb3168a893acd7897488fd71d497a9fe26b493d310'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ojo. Buen Profe PARA LABORATORIO. No tienen idea el sueño que da escuchar a este profe, explica MUY mal y es muy aburrido, pero da muy buena ayuda si uno la pide y califica relativamente suave. Muy buena gente y cordial. Si su equipo es bueno va a pasar bien, yo desde luego disfruté su clase'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c4f6ec093e50bddff35af63e67914004f9eaeb3c2ed65438fd2d34f8607b360c'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, '..."verdad"...'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'c1439db1ebd1856474af6b8190c2d2419b1fd6ab829a2bda53e9100b2931e3b2'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Las clases son muy aburridas y en la mayoría no se le entiende lo que está explicando. Se brinca pasos y llega a resultados que uno no sabe de dónde salieron por lo mismo. El profe es buena nota pero sin duda hay mejores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-12-29T00:00:00+00:00'::TIMESTAMPTZ, '8e2460fc16e1f6066f1799cecb615c379000902949f2a93018d6372aaceba2cd'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Es buena nota, pero no explica tan bien, hay que se muy autónomo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, '1c5243a8bb7a26fdd1329de5c0412e66c77f4258dd121363ccc0739ab1808fbd'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3dfdd7480792ec2e520fb97fbad3b67158a189b28727161b6626bf8e8143f234'::TEXT, ARRAY[3021]::BIGINT[]),
    (217::BIGINT, 'Muy mal profe, no explica para nada bien se enreda a cada rato, super aburrida me dormí 2 veces de lo aburrido que es, en las clases apenas resuelve ejercicios ya que va muy lento porque se enreda, no matricule con este profe quiérase un poco.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '251da6783485a197de1909fd5b52a1ec6e52fa1e0f27841ea53b401bbda68d2a'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'el peor profesor hasta el momento, se enreda solo se contradice todo el tiempo, la clase es muy aburrida ya que cada frase que termina la termina diciendo verdad, hágase el favor de no meterse con el, además que parece que borra los malos comentarios'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-09-23T00:00:00+00:00'::TIMESTAMPTZ, '21535d182ec6aced6cbcc6f2b462358a59375971ab5ace9977ed58c9aa435eb0'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Es buen profe ayuda muchísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, '24edcd5654050bc378cc2c0997ddd9db626f6b84e01819e0fd395ce65506fd10'::TEXT, ARRAY[607, 631]::BIGINT[]),
    (217::BIGINT, 'Muy buen profe. Explica los trabajos que manda la cátedra y da mucha ayuda. Hace que las evaluaciones sean muy fáciles, da mucho tiempo y siempre está disponible para ayudar. Las clases son super cortas y el profe va directo al grano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, '8d21c60a15f75425296610e4539557ba2279c05e3616778f9a8019d4c0abd9e8'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Explica bastante bien, las clases son cortas y se apega mucho con lo que dice la cátedra. Si hay alguna duda él no tiene problema en volver a explicar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-02T00:00:00+00:00'::TIMESTAMPTZ, '5836edaa20fd121bfe58301022734446f951b17d7b468ef37327ed363f1775c6'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Virtual. El profesor es muy buena persona y muy comprensivo. Las tareas y quices son de catedra y él se apega muy bien a lo que dice esta. Sus clases son amenas aunque a veces puede llegar a sentirse aburrida de vez en cuando. En general es un profe genial para el curso y lo recomiendo completamente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'a3608bff3570648052fc5cbf7a0ff37fbd681ad79a1a3a17a5fa5a9e16aa35c7'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ayuda mucho, hace clases cortas y al punto para dar tiempo necesario para hacer todos los trabajos. Es muy buena gente pero habla lento y es medio aburrido jajajaj'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'fa93f49f7514b2b8dace7914d0d3d7166bb56b7170aacb8b8e29ff5740d72127'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Es muy buen profe, clases cortas te explica todo lo que tenés que hacer de forma clara.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '01a48e8cc393fe96c82dc3bb4e92d42ec28acfb9cfc8ec3187f3cc82aedf7a19'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Todas las evaluaciones son de cátedra, pero las clases las explica super bien y de manera que uno comprenda, explica lo que hay que hacer para los trabajos y califica suave y ayuda a que uno entienda y pase. 10/10 este profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'd3e22933f83d86fba196df4f005b42656090441d89e9fe3cec87425fb0876df8'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Califica duro y quiere todo muy técnico, la mayoría de cosas son de cátedra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'afbbcb9a4adeb854fca7ca41ef0959ff674100e6441b30292a713061cb155f66'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'El mae es super chill. Metiendo con él el curso se pasa solo. Califica suave. Con solo poner atención a los videos donde explica exactamente como quiere los trabajos es suficiente para pegar 100. Si ocupa ayuda él siempre la va a dar. Habla demasiado despacio pero es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd59ea1f8af8961d02db303d11ee1861d788d39bd61946ff753a47f37039fcbea'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '20340f3cbf5cc281435b6eede294c3bbd4d7d700430df1e0ba19828be88161c9'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Es increíblemente aburrido, pero no es para nada mal profesor, ayuda bastante si se le pregunta y es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '4fe8d053629272e2e8087e68dfa545b28c91dd95caef604cdb60f07c05363761'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Es bueno y muy joven jajaja califica suave'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-07T00:00:00+00:00'::TIMESTAMPTZ, '43ed615dc6b2423a4e1c3d03525d94ebcf27debdb5a2d50c7bc38fd6b4c50205'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'En entorno virtual responde todas las dudas y muy rápido, califica muy suave, lo recomiendo bastante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'b7a463efa147ded123f7fd16cfc57df58c6bd543b4689351d827188766a92c2a'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Dificil calificarlo porque básicamente el curso se basó en hacer lo que decía la cátedra. Sin embargo, en las pocas semanas presenciales era claro (solo un poco aburrido) y en lo virtual SIEMPRE me contestó cualquier duda rápido y MUY amable. Full lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '319f8d8125d9d0750c2648fa1e91d0ab214b9ec20407abf2e61a765a0f1b4ea3'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Como la cátedra nos puso a ser autodidactas en este semestre virtual, es un toque difícil ratear a este profe. Aún así, se nota que ofrece ayuda para facilitar el curso (lo hace más fácil de lo que ya es). Es medio desordenado para calificar, pero en general explica bien cuando se necesita.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'd15c29cdb99b22bec7981eaab25fd2fd538cb4c6bbfe79be57b04d430bfeaa10'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Es buena gente, pero es muy aburrida su forma de explicar e incluso algo confusa, califica muy suave, solo es ser más autodidacta y se pasa fácil con este profesor.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '9210570b9b87eadf5841f3875c595a3c9e9d654bf95540fa27aecf433cce7b7a'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Es aburrido, pero se pase muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '0bf9cecc0bc1fc82ae0090213c3eb8136b795390e0a6c5839c50aeb48a2f97dd'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Demasiado aburrido, parece que el mae no tiene alma. Las clases se hacen largas por la falta de interés del profesor. Lo bueno es que los experimentos son muy fáciles entonces el curso es regalado, además que casi no hace quices. Si mete con él pasa de fijo pero es un bostezo'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2020-01-08T00:00:00+00:00'::TIMESTAMPTZ, '1cdbf8e5d7b297c210b6e6f4707ae604c99e103367d54a5e16bca2077d8a05b0'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ni bueno ni malo. El Lab se pasa solo, califica justo y hace quiz cuando se acuerda, sin avisar. Se puede matricular lab tranquilamente con él. "verdad"'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8ba117f77aec6afae03da4895ce71b8f83b1cb69f9e05bbe4e5c792e866d981a'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'El profe es demasiado tranquilo, hay que andar encima de él para que haga las cosas, la clase es un bostezo, califica suave, el curso casi que se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '01133d5245d7b5b12ea2603489f092b67137e1ce22d9351b8910b9bbd65823c0'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'No es bueno para explicar, es bastante confuso. No califica duro, solo con los informes es más estricto.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '6e2331059e7fdd759d6233ba90299bad801cbbc535478a9c90a72fae963faeeb'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Muy bueno!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1e7415a7a81dfa65f9a16c1d97926c5526575fa33c51d74ab4e5bfb768402af8'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'El profe es normal, no es el mejor. Lee una presentación en todas las clases y en la mayoría de ejercicios se confunde y se ve inseguro de lo que está haciendo. Sabe mucho sobre física pero no es tan bueno explicando. Los quices son por medio del TEC-Digital y se preocupa por que todo quede claro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, '77a027bbf1dc72e60469ed99913832b54d2936fa610210cfaebfb7ee84b4eb59'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Se interesa porque los estudiantes aprendan, explica bien la teoría y hace bastantes ejercicios, quices en el TECDigital, buena gente!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '220555db8b81088b7f4d99eb7fcba6d507af6f4cbe76826f910734773aa39225'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Es un curso súper fácil. Si tiene dudas el profe es bastante accesible'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3932a8515ffba9970d5605fe6b9a43909c5f4268c2f332687084a2ba93c48c82'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7629cbc4846f534824b00b39b5aafe4406dbd29b6e794a7ff35debc2406fe25f'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fcdfa16f1127e560f0272c9120bba142c33258e970e13be31c3fce86d55fdfc1'::TEXT, ARRAY[3021]::BIGINT[]),
    (217::BIGINT, 'El curso es fácil, pero aún así en ocasiones no se explicaba de la mejor manera, no me gustaría llevar teoría con él por ese motivo. Pero tampoco es el peor profe'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'eb520d502bc90172ee326fe0737d2ad5fa6ec6b5fb1b889328724df73a907f9a'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'De los peores profesores que he tenido. No se aprende NADA con él. El curso fue una pérdida de tiempo.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '7a3abbf27bee28b3213d16891f15fbbc4dd3f365fd983018e101d674e6bb88e4'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Su clase se vuelve muy pesada en ocasiones, aunque a veces hace bromas, califica suave.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'dcbefa7d5748eca865d6fe2c647855a1850b9ba60647d4ae17f6500938c68476'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5f078d032d39c8f72febf8c7694d7d80d294d777e63c8f36f754b0e591108b04'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'db434b8b44bda619add5ee1a364a0ca12caf18a4ce2cfdda4e6433fb0c8a1fdc'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'El Profe es muy tuanis como persona, durante las clases trata de explicar bien, aunque en algunas ocasiones se enreda un toque. Los quices y tareas son accesibles. A veces, las tareas se encuentran en internet, califica justo y en consulta procura evacuar dudas lo mejor posible.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0bfb9d085eb41d3cfde313917d0d328f106c82913899e35d4611a8575e9072c9'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Un poco sistemático, hace quices cuando se acuerda, examenes sencillos, cuesta entenderle a veces, pero siempre dice o recuerda lo necesario por utilizar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3236fcd614ea4614718e7bf539d0582dc6c69c8620deb96f75cf4c917c5dbd8c'::TEXT, ARRAY[607]::BIGINT[]),
    (217::BIGINT, 'Las notas de clase que da son muy útiles, realiza bastantes problemas, yo si matricularia otro curso con el.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'c596363bd5621207e50f5919cd734c73c8abff679ecdf528e19bd70362c90365'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'No explica bien, mal profesor. No volvería nunca ahí.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f186c07785329690d0293c22c2ea150d35cda829e2dee75d5e118caedc9ccac5'::TEXT, ARRAY[604]::BIGINT[]),
    (217::BIGINT, 'Es un poco aburrido, pero con lo a que apunta en la pizarra una va preparado para el examen, tareas sacadas de internet. Es buena gente y califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-11-03T00:00:00+00:00'::TIMESTAMPTZ, '88f5f34e400c4c3e5cf57c99b038c69088b1b74190f0ff08ac296115c174fd43'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b61cefd4ed21f3a798cf332bf1fd98f53aea96032ee877af92305a7adfa62fa9'::TEXT, ARRAY[631]::BIGINT[]),
    (217::BIGINT, 'Se enreda aveces, clases muy practicas sin mucha teoría, es serio pero buena gente y aveces hace chistes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c53a031a24cd3d272604dd2ce0b489b1dc859b1b9909c4e5204d995448bb19ff'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'muy buen profe, ayuda bastante, explica bien y los quices son muy fáciles. El curso es muy dificil pero con él se pasa bien nada mas de ponerle bastante y él hace bastante practica.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '750cf9402ff4a47ed2e5fe52fcba98101e40db7f82fdd1286d190e2b906c37d7'::TEXT, ARRAY[631]::BIGINT[]),
    (217::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7db9c847e4ab8213677f36437b95638435041dc4d3501e621f8db997f56255b4'::TEXT, ARRAY[631]::BIGINT[]),
    (217::BIGINT, 'Explica muy bien aunque de vez en cuando se enreda, califica suave(muy suave). Da mucha teoría y los ejemplos que da son muy similares a los de los exámenes, en general recomendadísimo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6f588034071c8a846b87f49ff7105f5ac8fb17bd0f4d8e98e3c6b8ecfaf76b74'::TEXT, ARRAY[922]::BIGINT[]),
    (217::BIGINT, 'Buen profe para laboratorio, aclara las dudas que uno tenga y da tiempo para que uno entregue los informes y los devuelve calificados y con las respectivas observaciones, Los quices se resuelven fácil si uno hizo el preinforme. el profe es muy amable y buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '6f1ca791414b776feb8301a591bb0006692ec51654a793998584a31b42c9b778'::TEXT, ARRAY[631]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
